CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_owner ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.workspaces TO authenticated; GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workspace_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), user_id uuid NOT NULL, role text NOT NULL DEFAULT 'member', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id), CONSTRAINT member_role CHECK (role IN ('owner','reviewer','member')));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE INDEX workspace_members_user ON public.workspace_members(user_id);
CREATE FUNCTION public.is_workspace_member(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=w AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_workspace_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_workspace_member(uuid) TO authenticated;
CREATE POLICY members_read ON public.workspace_members FOR SELECT TO authenticated USING (public.is_workspace_member(workspace_id));
CREATE POLICY workspace_read ON public.workspaces FOR SELECT TO authenticated USING (public.is_workspace_member(id));
CREATE POLICY workspace_update ON public.workspaces FOR UPDATE TO authenticated USING (owner_id=auth.uid()) WITH CHECK (owner_id=auth.uid());
CREATE FUNCTION public.create_workspace(workspace_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(workspace_name)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Workspace name must be 1–100 characters'; END IF; INSERT INTO public.workspaces(name,owner_id) VALUES(trim(workspace_name),auth.uid()) RETURNING id INTO w; INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(w,auth.uid(),'owner'); RETURN w; END $$;
REVOKE ALL ON FUNCTION public.create_workspace(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_workspace(text) TO authenticated;
ALTER TABLE public.files ADD COLUMN workspace_id uuid REFERENCES public.workspaces(id);
ALTER TABLE public.processing_jobs ADD COLUMN workspace_id uuid REFERENCES public.workspaces(id);
ALTER TABLE public.approval_requests ADD COLUMN workspace_id uuid REFERENCES public.workspaces(id);
CREATE INDEX files_workspace ON public.files(workspace_id,created_at);
CREATE INDEX jobs_workspace ON public.processing_jobs(workspace_id,created_at);
DROP POLICY files_owner ON public.files;
CREATE POLICY files_read ON public.files FOR SELECT TO authenticated USING ((workspace_id IS NULL AND user_id=auth.uid()) OR public.is_workspace_member(workspace_id));
CREATE POLICY files_insert ON public.files FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND public.is_workspace_member(workspace_id));
DROP POLICY jobs_owner ON public.processing_jobs;
CREATE POLICY jobs_read ON public.processing_jobs FOR SELECT TO authenticated USING ((workspace_id IS NULL AND user_id=auth.uid()) OR public.is_workspace_member(workspace_id));
CREATE POLICY jobs_insert ON public.processing_jobs FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND public.is_workspace_member(workspace_id) AND EXISTS(SELECT 1 FROM public.files f WHERE f.id=file_id AND f.user_id=auth.uid() AND f.workspace_id=processing_jobs.workspace_id) AND status='Awaiting Review' AND progress IS NULL);
DROP POLICY approvals_owner ON public.approval_requests;
CREATE POLICY approvals_read ON public.approval_requests FOR SELECT TO authenticated USING ((workspace_id IS NULL AND user_id=auth.uid()) OR public.is_workspace_member(workspace_id));
CREATE TABLE public.videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), file_id uuid NOT NULL UNIQUE REFERENCES public.files(id), duration_seconds double precision, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.videos TO authenticated; GRANT ALL ON public.videos TO service_role; ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.videos FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.video_speakers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), video_id uuid NOT NULL REFERENCES public.videos(id), label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_speakers TO authenticated; GRANT ALL ON public.video_speakers TO service_role; ALTER TABLE public.video_speakers ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.video_speakers FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.transcript_segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), video_id uuid NOT NULL REFERENCES public.videos(id), speaker_id uuid REFERENCES public.video_speakers(id), start_seconds double precision NOT NULL, end_seconds double precision NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.transcript_segments TO authenticated; GRANT ALL ON public.transcript_segments TO service_role; ALTER TABLE public.transcript_segments ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.transcript_segments FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.speaker_turns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), speaker_id uuid NOT NULL REFERENCES public.video_speakers(id), start_seconds double precision NOT NULL, end_seconds double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.speaker_turns TO authenticated; GRANT ALL ON public.speaker_turns TO service_role; ALTER TABLE public.speaker_turns ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.speaker_turns FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.video_frames (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), video_id uuid NOT NULL REFERENCES public.videos(id), timestamp_seconds double precision NOT NULL, storage_path text NOT NULL, size_bytes bigint NOT NULL, sha256 text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_frames TO authenticated; GRANT ALL ON public.video_frames TO service_role; ALTER TABLE public.video_frames ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.video_frames FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.slide_intervals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), video_id uuid NOT NULL REFERENCES public.videos(id), frame_id uuid NOT NULL REFERENCES public.video_frames(id), start_seconds double precision NOT NULL, end_seconds double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.slide_intervals TO authenticated; GRANT ALL ON public.slide_intervals TO service_role; ALTER TABLE public.slide_intervals ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.slide_intervals FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), file_id uuid NOT NULL UNIQUE REFERENCES public.files(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role; ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.documents FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.document_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), document_id uuid NOT NULL REFERENCES public.documents(id), page_number integer NOT NULL, content text, storage_path text, size_bytes bigint, sha256 text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.document_pages TO authenticated; GRANT ALL ON public.document_pages TO service_role; ALTER TABLE public.document_pages ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.document_pages FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.document_slides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), document_id uuid NOT NULL REFERENCES public.documents(id), slide_number integer NOT NULL, content text, storage_path text, size_bytes bigint, sha256 text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.document_slides TO authenticated; GRANT ALL ON public.document_slides TO service_role; ALTER TABLE public.document_slides ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.document_slides FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.duplicate_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), method text NOT NULL, status text NOT NULL DEFAULT 'Awaiting Review', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.duplicate_groups TO authenticated; GRANT ALL ON public.duplicate_groups TO service_role; ALTER TABLE public.duplicate_groups ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.duplicate_groups FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.duplicate_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), group_id uuid NOT NULL REFERENCES public.duplicate_groups(id), file_id uuid NOT NULL REFERENCES public.files(id), similarity double precision, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.duplicate_matches TO authenticated; GRANT ALL ON public.duplicate_matches TO service_role; ALTER TABLE public.duplicate_matches ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.duplicate_matches FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.knowledge_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), file_id uuid NOT NULL REFERENCES public.files(id), content text NOT NULL, source_reference jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.knowledge_chunks TO authenticated; GRANT ALL ON public.knowledge_chunks TO service_role; ALTER TABLE public.knowledge_chunks ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.knowledge_chunks FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.storage_analytics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), file_id uuid NOT NULL REFERENCES public.files(id), generated_size_bytes bigint NOT NULL, package_verified_at timestamptz, reclaimed_size_bytes bigint NOT NULL DEFAULT 0, retention_verified_at timestamptz, approval_id uuid REFERENCES public.approval_requests(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(generated_size_bytes>=0 AND reclaimed_size_bytes>=0));
GRANT SELECT ON public.storage_analytics TO authenticated; GRANT ALL ON public.storage_analytics TO service_role; ALTER TABLE public.storage_analytics ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.storage_analytics FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.optimization_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), file_id uuid NOT NULL REFERENCES public.files(id), reason text NOT NULL, status text NOT NULL DEFAULT 'Awaiting Review', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.optimization_recommendations TO authenticated; GRANT ALL ON public.optimization_recommendations TO service_role; ALTER TABLE public.optimization_recommendations ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.optimization_recommendations FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.offboarding_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), name text NOT NULL, inventory_path text, status text NOT NULL DEFAULT 'Awaiting service', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.offboarding_cases TO authenticated; GRANT ALL ON public.offboarding_cases TO service_role; ALTER TABLE public.offboarding_cases ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.offboarding_cases FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), user_id uuid NOT NULL, file_id uuid REFERENCES public.files(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role; ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.activity_logs FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
CREATE TABLE public.reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), name text NOT NULL, kind text NOT NULL, storage_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reports TO authenticated; GRANT ALL ON public.reports TO service_role; ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY; CREATE POLICY workspace_read ON public.reports FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['videos','video_speakers','transcript_segments','speaker_turns','video_frames','slide_intervals','documents','document_pages','document_slides','duplicate_groups','duplicate_matches','knowledge_chunks','storage_analytics','optimization_recommendations','offboarding_cases','activity_logs','reports'] LOOP EXECUTE format('CREATE INDEX %I ON public.%I(workspace_id,created_at)', t||'_workspace',t); END LOOP; END $$;
CREATE FUNCTION public.audit_file_registration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.workspace_id IS NOT NULL THEN INSERT INTO public.activity_logs(workspace_id,user_id,file_id,action) VALUES(NEW.workspace_id,NEW.user_id,NEW.id,'Original registered'); END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_file_registered AFTER INSERT ON public.files FOR EACH ROW EXECUTE FUNCTION public.audit_file_registration();